/* Get the GTM_GENERIC APP version. */
ACS_APP_VERSION_t GTM_GENERIC_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = GTM_GENERIC_MAJOR_VERSION;
  version.minor = GTM_GENERIC_MINOR_VERSION;
  version.patch = GTM_GENERIC_PATCH_VERSION;

  return version;
}

/* Function to initialize the GTM clock frequencies and trigger connections. */
GTM_GENERIC_STATUS_t GTM_GENERIC_Init(GTM_GENERIC_t * handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_GTM *gtm = handle->app_config->gtm_module;

  if (!handle->app_is_initialized)
  {
    uint32 mask = 0, shift = 0;
    uint32 value = 2;

    /* Enable EGTM, it is necessary if the EGTM is not initialized earlier */
    IfxGtm_enable(gtm);

    /* Set the GTM global clock frequency */
    IfxGtm_Cmu_setGclkFrequency(gtm, (float32)handle->app_config->cmu.gclk);

    /* Set the GTM configurable clock frequency */
    for (uint32 i = 0; i < 8 ; i++)
    {
      if (handle->app_config->cmu.clk_en[i])
      {
        IfxGtm_Cmu_setClkFrequency(gtm, i, (float32)handle->app_config->cmu.clk[i]);
        mask = mask | (value << shift);
      }
      shift += 2;
    }

    /* Set the GTM external clock frequency */
    for (uint32 i = 0; i < 3 ; i++)
    {
      if (handle->app_config->cmu.eclk_en[i])
      {
        IfxGtm_Cmu_setEclkFrequency(gtm, i, (float32)handle->app_config->cmu.eclk[i]);
        mask = mask | (value << shift);
      }
      shift += 2;
    }

    if (handle->app_config->cmu.fxclk_en)
    {
      mask = mask | (value << shift);
    }

    /* Enable the required clocks */
    IfxGtm_Cmu_enableClocks(gtm, mask);

    /* Configures the tout selection */
    for (uint32 i = 0; i < handle->app_config->toutsel.num; i++)
    {
      IfxGtm_Tom_setTout(handle->app_config->toutsel.conf[i].tout_num, handle->app_config->toutsel.conf[i].tout_sel);
    }

    /* Configures the adctrigout0 selection */
    for (uint32 i = 0; i < handle->app_config->adctrigout0.num; i++)
    {
      uint32 adcTrig = (handle->app_config->adctrigout0.conf[i].adctrigout0_num >> 3);
      uint32 shift   = (handle->app_config->adctrigout0.conf[i].adctrigout0_num & 0x7U) * 4;
      uint32 value   = handle->app_config->adctrigout0.conf[i].adctrigout0_sel << shift;
      uint32 mask    = 0xFU << shift;
      __ldmst_c(&(MODULE_GTM.ADCTRIG[adcTrig].OUT0.U), mask, value);
    }

    /* Configures the adctrigout1 selection */
    for (uint32 i = 0; i < handle->app_config->adctrigout1.num; i++)
    {
      uint32 adcTrig = (handle->app_config->adctrigout1.conf[i].adctrigout1_num >> 2);
      uint32 shift   = (handle->app_config->adctrigout1.conf[i].adctrigout1_num & 0x3U) * 4;
      uint32 value   = handle->app_config->adctrigout1.conf[i].adctrigout1_sel << shift;
      uint32 mask    = 0xFU << shift;
      __ldmst_c(&(MODULE_GTM.ADCTRIG[adcTrig].OUT1.U), mask, value);
    }

#ifdef GTM_GENERIC_EDSADC_EXISTS
    /* Configures the dsadcoutsel selection */
    for (uint32 i = 0; i < handle->app_config->dsadcoutsel.num; i++)
    {
      IfxGtm_Trig_toEdsadc(gtm,
                          (handle->app_config->dsadcoutsel.conf[i].dsadcoutsel_num % 6),
                          (handle->app_config->dsadcoutsel.conf[i].dsadcoutsel_num / 6),
                          handle->app_config->dsadcoutsel.conf[i].dsadcoutsel_sel);
    }
#endif
    handle->app_is_initialized = TRUE;
  }

  return GTM_GENERIC_STATUS_SUCCESS;
}

/* Function to trigger AGC channels host trigger. */
void GTM_GENERIC_Agc_Trigger(GTM_GENERIC_t *handle, uint32 cluster)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_GTM *gtm = handle->app_config->gtm_module;

  IfxGtm_Atom_Agc_trigger(&(gtm->ATOM[cluster].AGC));
}

/* Function to configure and use time base trigger in AGC. */
void GTM_GENERIC_Agc_Time_Trigger(GTM_GENERIC_t *handle, uint32 cluster, IfxGtm_Tbu_Ts base, uint32 value)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_GTM *gtm = handle->app_config->gtm_module;

  IfxGtm_Tbu_disableChannel(gtm, base);
  IfxGtm_Atom_Agc_setTimeTrigger(&(gtm->ATOM[cluster].AGC), base, value);
  IfxGtm_Atom_Agc_enableTimeTrigger(&(gtm->ATOM[cluster].AGC), TRUE);
  IfxGtm_Tbu_setChannelBase(gtm, base, 0);
  IfxGtm_Tbu_enableChannel(gtm, base);
}

/* Function to trigger TGC channels host trigger. */
void GTM_GENERIC_Tgc_Trigger(GTM_GENERIC_t *handle, uint32 cluster, uint32 tgcno)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_GTM         *gtm = handle->app_config->gtm_module;
  Ifx_GTM_TOM_TGC *tgc;

  if (tgcno == 0)
  {
    tgc = (Ifx_GTM_TOM_TGC *)&(gtm->TOM[cluster].TGC0_GLB_CTRL);
  }
  else
  {
    tgc = (Ifx_GTM_TOM_TGC *)&(gtm->TOM[cluster].TGC1_GLB_CTRL);
  }
  IfxGtm_Tom_Tgc_trigger(tgc);
}

/* Function to configure and use time base trigger in TGC. */
void GTM_GENERIC_Tgc_Time_Trigger(GTM_GENERIC_t *handle, uint32 cluster, uint32 tgcno, IfxGtm_Tbu_Ts base, uint32 value)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_GTM         *gtm = handle->app_config->gtm_module;
  Ifx_GTM_TOM_TGC *tgc;

  if (tgcno == 0)
  {
    tgc = (Ifx_GTM_TOM_TGC *)&(gtm->TOM[cluster].TGC0_GLB_CTRL);
  }
  else
  {
    tgc = (Ifx_GTM_TOM_TGC *)&(gtm->TOM[cluster].TGC1_GLB_CTRL);
  }
  IfxGtm_Tbu_disableChannel(gtm, base);
  IfxGtm_Tom_Tgc_setTimeTrigger(tgc, base, value);
  IfxGtm_Tom_Tgc_enableTimeTrigger(tgc, TRUE);
  IfxGtm_Tbu_setChannelBase(gtm, base, 0);
  IfxGtm_Tbu_enableChannel(gtm, base);
}

